const target = $('Validate & Normalize').item.json.target;
const lines = ($json.stdout || '').split('\n');
const records = { A: [], AAAA: [], MX: [], NS: [], TXT: [], SOA: [] };
let section = null;
for (const line of lines) {
  const t = line.trim();
  if (!t) continue;
  const marker = t.match(/^(A|AAAA|MX|NS|TXT|SOA):$/);
  if (marker) { section = marker[1]; continue; }
  if (section && records[section]) records[section].push(t);
}
return [{ json: { target, records } }];

const dnsInfo = $('Parse DNS').item.json;
const norm = $('Validate & Normalize').item.json;
let subdomains = [];
try {
  const body = $json.body !== undefined ? $json.body : $json;
  const arr = Array.isArray(body) ? body : [];
  const set = new Set();
  for (const entry of arr) {
    if (entry && entry.name_value) {
      entry.name_value.split('\n').forEach(n => set.add(n.trim().toLowerCase()));
    }
  }
  subdomains = Array.from(set);
} catch (e) { subdomains = []; }

let whoisText = '';
try { whoisText = $('WHOIS Lookup').item.json.stdout || ''; } catch (e) { whoisText = ''; }
const whoisFields = {};
for (const line of whoisText.split('\n')) {
  const m = line.match(/^\s*(Registrar|Registrant Organization|Creation Date|Registry Expiry Date|Name Server|Updated Date)\s*:\s*(.+)$/i);
  if (m) {
    const key = m[1].trim();
    whoisFields[key] = whoisFields[key] ? [].concat(whoisFields[key], m[2].trim()) : m[2].trim();
  }
}

const resolvedIp = norm.isIp ? norm.target : ((dnsInfo.records.A && dnsInfo.records.A[0]) || null);

const attckCoverage = [
  { technique: 'T1590.002', name: 'Gather Victim Network Information: DNS', status: 'executed' },
  { technique: 'T1596.003', name: 'Search Open Technical Databases: Digital Certificates', status: subdomains.length || !norm.isIp ? 'executed' : 'skipped (IP target, no hostname to query)' },
  { technique: 'T1596.002', name: 'Search Open Technical Databases: WHOIS', status: whoisText ? 'executed' : 'no data returned' },
];

return [{ json: {
  target: norm.target, isIp: norm.isIp, scanIntensity: norm.scanIntensity,
  dns: dnsInfo.records, subdomains, whois: whoisFields, resolvedIp, attckCoverage
} }];

const ctx = $('Merge DNS + Subdomains').item.json;
const xml = $json.stdout || '';
const ports = [];
const portBlockRe = /<port protocol="(\w+)" portid="(\d+)">([\s\S]*?)<\/port>/g;
let pm;
while ((pm = portBlockRe.exec(xml)) !== null) {
  const [, protocol, portid, block] = pm;
  const stateMatch = block.match(/<state state="(\w+)"/);
  if (!stateMatch || stateMatch[1] !== 'open') continue;
  const serviceTagMatch = block.match(/<service\b[^>]*\/?>/);
  let service = 'unknown', product = null, version = null;
  if (serviceTagMatch) {
    const tag = serviceTagMatch[0];
    service = (tag.match(/name="([^"]*)"/) || [])[1] || 'unknown';
    product = (tag.match(/product="([^"]*)"/) || [])[1] || null;
    version = (tag.match(/version="([^"]*)"/) || [])[1] || null;
  }
  const scripts = [];
  const scriptRe = /<script id="([^"]*)"[^>]*output="([^"]*)"[^>]*>([\s\S]*?)<\/script>|<script id="([^"]*)"[^>]*output="([^"]*)"\s*\/>/g;
  let sm;
  while ((sm = scriptRe.exec(block)) !== null) {
    const id = sm[1] || sm[4];
    const rawOutput = sm[2] || sm[5];
    const inner = sm[3] || '';
    const cleanOutput = rawOutput.replace(/&#10;/g, ' ').replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim().slice(0, 300);
    if (id === 'vulners') {
      const cves = [];
      // <elem> field order inside each vulners <table> block is not
      // guaranteed (observed cvss,type,id,is_exploit against a real target,
      // not the is_exploit,cvss,id,type order this originally assumed) -
      // parse each inner <table>...</table> block into a key/value map
      // instead of matching a fixed sequence, order-independent.
      const innerTableRe = /<table>([\s\S]*?)<\/table>/g;
      const elemRe = /<elem key="([^"]+)">([^<]*)<\/elem>/g;
      let vm;
      while ((vm = innerTableRe.exec(inner)) !== null) {
        const fields = {};
        elemRe.lastIndex = 0;
        let em;
        while ((em = elemRe.exec(vm[1])) !== null) fields[em[1]] = em[2];
        if (fields.id && fields.cvss) {
          cves.push({ id: fields.id, type: fields.type || 'unknown', cvss: Number(fields.cvss), isExploit: fields.is_exploit === 'true' });
        }
      }
      if (cves.length) scripts.push({ id, output: cleanOutput, cves });
      continue;
    }
    scripts.push({ id, output: cleanOutput });
  }
  ports.push({ port: Number(portid), protocol, service, product, version, scripts });
}
const coverage = [...ctx.attckCoverage, { technique: 'T1595.001/.002', name: 'Active Scanning: Scanning IP Blocks / Vulnerability Scanning', status: 'executed' }];
return [{ json: { ...ctx, attckCoverage: coverage, portScan: { skipped: false, openPorts: ports } } }];

const ctx = $('Merge DNS + Subdomains').item.json;
const coverage = [...ctx.attckCoverage, { technique: 'T1595.001/.002', name: 'Active Scanning: Scanning IP Blocks / Vulnerability Scanning', status: 'skipped (scanIntensity=dns-only or no resolvable IP)' }];
return [{ json: { ...ctx, attckCoverage: coverage, portScan: { skipped: true, reason: 'scanIntensity=dns-only or no resolvable IP' } } }];

const ctx = $json;
const target = ctx.target;
const maxPages = 10;
const maxDepth = 2;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const politeDelay = () => sleep(400 + Math.floor(Math.random() * 500));
const visited = new Set();
const fetchUrl = async (url) => {
  try {
    await politeDelay();
    return await this.helpers.httpRequest({ method: 'GET', url, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  } catch (e) { return null; }
};

const getOrigin = (u) => u.endsWith('/') ? u.slice(0, -1) : u;
const resolveHref = (href, baseUrl, origin) => {
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return (origin.startsWith('https') ? 'https:' : 'http:') + href;
  if (href.startsWith('/')) return origin + href;
  const baseDir = baseUrl.slice(0, baseUrl.lastIndexOf('/') + 1);
  return baseDir + href;
};

const openPorts = (ctx.portScan && !ctx.portScan.skipped) ? ctx.portScan.openPorts.map(p => p.port) : [];
const candidateUrls = [];
if (openPorts.includes(443)) candidateUrls.push(`https://${target}/`);
if (openPorts.includes(80)) candidateUrls.push(`http://${target}/`);
for (const p of openPorts) {
  if (p !== 80 && p !== 443) candidateUrls.push(`http://${target}:${p}/`);
}

let startUrl = null, homepage = null;
if (candidateUrls.length === 0) {
  const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'no open ports discovered to attempt a web scan against' }];
  return [{ json: { ...ctx, attckCoverage: coverage, webScan: { skipped: false, reachable: false, reason: 'no open ports from port scan' } } }];
}
for (const url of candidateUrls) {
  homepage = await fetchUrl(url);
  if (homepage) { startUrl = url; break; }
}
if (!homepage) {
  const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'attempted, target unreachable' }];
  return [{ json: { ...ctx, attckCoverage: coverage, webScan: { skipped: false, reachable: false, portsTried: candidateUrls } } }];
}
const origin = getOrigin(startUrl);

const SECURITY_HEADERS = [
  'strict-transport-security', 'content-security-policy', 'x-frame-options',
  'x-content-type-options', 'referrer-policy', 'permissions-policy',
];
const auditHeaders = (headers) => {
  const present = {}, missing = [];
  for (const h of SECURITY_HEADERS) {
    if (headers[h]) present[h] = headers[h];
    else missing.push(h);
  }
  return { present, missing };
};

const auditCookies = (headers) => {
  let raw = headers['set-cookie'];
  if (!raw) return [];
  if (!Array.isArray(raw)) raw = [raw];
  return raw.map((c) => {
    const name = c.split('=')[0];
    return {
      name,
      secure: /;\s*Secure/i.test(c),
      httpOnly: /;\s*HttpOnly/i.test(c),
      sameSite: (c.match(/;\s*SameSite=(\w+)/i) || [])[1] || 'not set',
    };
  });
};

const extractForms = (body, pageUrl) => {
  const forms = [];
  const formRe = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
  let fm;
  while ((fm = formRe.exec(body)) !== null) {
    const attrs = fm[1];
    const action = (attrs.match(/action=["']([^"']*)["']/i) || [])[1] || pageUrl;
    const method = ((attrs.match(/method=["']([^"']*)["']/i) || [])[1] || 'GET').toUpperCase();
    const inputs = [];
    const inputRe = /<input\b[^>]*name=["']([^"']+)["'][^>]*>/gi;
    let im;
    while ((im = inputRe.exec(fm[2])) !== null) inputs.push(im[1]);
    if (inputs.length) forms.push({ page: pageUrl, action, method, fields: inputs });
  }
  return forms;
};

const headers = homepage.headers || {};
const homepageBody = typeof homepage.body === 'string' ? homepage.body : '';
const securityHeaders = auditHeaders(headers);
const cookies = auditCookies(headers);
let forms = extractForms(homepageBody, startUrl);

// --- JS/CSS asset discovery + bundle analysis ---
// Modern SPAs (Angular/React/Vue) don't expose their real attack surface via
// server-rendered HTML - the actual routes and REST/API paths only exist as
// strings inside the compiled JS bundle. A static path wordlist alone will
// never find these. Fetch the referenced JS assets and pull real path
// fragments out of them instead of guessing.
const assetRe = /(?:src|href)=["']([^"']+\.(?:js|css))["']/gi;
const assetPaths = new Set();
let am;
while ((am = assetRe.exec(homepageBody)) !== null) assetPaths.add(am[1]);
const jsAssetUrls = Array.from(assetPaths)
  .filter((a) => a.endsWith('.js'))
  .map((a) => resolveHref(a, startUrl, origin))
  .filter((u) => u.startsWith(origin));

let bundleEvidence = [], discoveredApiPaths = [];
for (const assetUrl of jsAssetUrls.slice(0, 6)) {
  const res = await fetchUrl(assetUrl);
  if (!res || typeof res.body !== 'string') continue;
  const body = res.body;
  const pathRe = /\/(?:rest|api)\/[a-zA-Z0-9_\-\/]+/g;
  const hits = new Set();
  let pm;
  while ((pm = pathRe.exec(body)) !== null) hits.add(pm[0].replace(/\/$/, ''));
  for (const h of hits) discoveredApiPaths.push(h);
  const generator = body.match(/<meta\s+name=["']generator["']\s+content=["']([^"']+)["']/i);
  if (generator) bundleEvidence.push(`meta generator tag: "${generator[1]}"`);
}
discoveredApiPaths = Array.from(new Set(discoveredApiPaths)).slice(0, 40);

const comments = homepageBody.match(/<!--[\s\S]{0,200}?-->/g) || [];
for (const c of comments.slice(0, 5)) {
  const text = c.replace(/<!--|-->/g, '').trim();
  if (text) bundleEvidence.push(`HTML comment: "${text.slice(0, 150)}"`);
}
for (const a of Array.from(assetPaths).slice(0, 30)) bundleEvidence.push(`asset reference: ${a}`);
const fingerprint = {
  assetCount: assetPaths.size,
  evidenceStrings: bundleEvidence,
  jsAssetUrls,
};

// --- Baselined content discovery: static wordlist + real endpoints pulled
// from the JS bundle, so discovery isn't limited to guessed common paths. ---
const COMMON_PATHS = [
  '/robots.txt', '/sitemap.xml', '/.well-known/security.txt', '/.git/HEAD',
  '/.env', '/admin', '/api', '/graphql', '/swagger.json', '/swagger-ui.html',
  '/package.json', '/server-status', '/.htaccess', '/actuator/health', '/login',
];
const probePaths = Array.from(new Set([...COMMON_PATHS, ...discoveredApiPaths]));

const simpleHash = (s) => { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return h; };
const baselinePath = `/__recon_baseline_${Date.now()}_${Math.floor(Math.random() * 1e6)}__`;
const baselineRes = await fetchUrl(`${origin}${baselinePath}`);
const baseline = baselineRes ? {
  status: baselineRes.statusCode,
  length: (typeof baselineRes.body === 'string' ? baselineRes.body.length : 0),
  hash: simpleHash(typeof baselineRes.body === 'string' ? baselineRes.body : ''),
} : null;

const pathResults = [];
for (const p of probePaths) {
  const res = await fetchUrl(`${origin}${p}`);
  if (!res) continue;
  const body = typeof res.body === 'string' ? res.body : '';
  const signature = { status: res.statusCode, length: body.length, hash: simpleHash(body) };
  const matchesBaseline = baseline && signature.status === baseline.status &&
    signature.length === baseline.length && signature.hash === baseline.hash;
  pathResults.push({
    path: p,
    status: res.statusCode,
    distinctFromBaseline: !matchesBaseline,
    fromJsBundle: discoveredApiPaths.includes(p),
  });
}

const queue = [{ url: startUrl, depth: 1 }];
const pages = [];
while (queue.length && pages.length < maxPages) {
  const { url, depth } = queue.shift();
  if (visited.has(url)) continue;
  visited.add(url);
  const res = await fetchUrl(url);
  if (!res) continue;
  const body = typeof res.body === 'string' ? res.body : '';
  const titleMatch = body.match(/<title[^>]*>([^<]*)<\/title>/i);
  pages.push({ url, status: res.statusCode, title: titleMatch ? titleMatch[1].trim() : null });
  if (url !== startUrl) forms = forms.concat(extractForms(body, url));
  if (depth < maxDepth) {
    const hrefRe = /href=["']([^"'#]+)["']/gi;
    let hm;
    while ((hm = hrefRe.exec(body)) !== null) {
      try {
        const abs = resolveHref(hm[1], url, origin);
        if (abs.startsWith(origin) && !visited.has(abs) && (queue.length + pages.length) < maxPages) {
          queue.push({ url: abs, depth: depth + 1 });
        }
      } catch (e) {}
    }
  }
}
let robotsStatus = null, sitemapStatus = null;
const robotsRes = pathResults.find((r) => r.path === '/robots.txt');
if (robotsRes) robotsStatus = robotsRes.status;
const sitemapRes = pathResults.find((r) => r.path === '/sitemap.xml');
if (sitemapRes) sitemapStatus = sitemapRes.status;

const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'executed' }];
return [{ json: { ...ctx, attckCoverage: coverage, webScan: {
  skipped: false, reachable: true, origin,
  headers,
  securityHeaders,
  cookies,
  fingerprint,
  discoveredApiPaths,
  forms,
  contentDiscovery: pathResults,
  robotsTxtStatus: robotsStatus, sitemapXmlStatus: sitemapStatus,
  pagesCrawled: pages.length, pages
} } }];

const data = $json;
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const ts = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

// Trim the payload that goes to the LLM - drop redundant/verbose fields so
// the prompt stays small enough for the model to reliably follow the
// requested report structure instead of drowning in raw data.
let promptWebScan = null;
if (data.webScan) {
  const ws = data.webScan;
  promptWebScan = {
    reachable: ws.reachable,
    reason: ws.reason,
    origin: ws.origin,
    securityHeaders: ws.securityHeaders,
    cookies: ws.cookies,
    fingerprint: ws.fingerprint ? {
      assetCount: ws.fingerprint.assetCount,
      evidenceStrings: ws.fingerprint.evidenceStrings,
    } : undefined,
    forms: ws.forms,
    contentDiscovery: (ws.contentDiscovery || []).filter(r => r.distinctFromBaseline),
    contentDiscoveryCheckedCount: (ws.contentDiscovery || []).length,
    pagesCrawledCount: ws.pagesCrawled,
    robotsTxtStatus: ws.robotsTxtStatus,
    sitemapXmlStatus: ws.sitemapXmlStatus,
  };
}

const promptData = {
  target: data.target, isIp: data.isIp, scanIntensity: data.scanIntensity,
  dns: data.dns, subdomains: data.subdomains, whois: data.whois, resolvedIp: data.resolvedIp,
  attckCoverage: data.attckCoverage, portScan: data.portScan,
  webScan: promptWebScan,
  componentFindings: data.componentFindings,
  sqlmapScan: data.sqlmapScan,
  zapScan: data.zapScan,
  sensitiveFileExposures: data.sensitiveFileExposures,
};

return [{ json: { ...data, reportTimestamp: ts, reportFilename: `${data.target}-${ts}.md`, promptData } }];

const ctx = $json;
const header = `# Recon Report: ${ctx.target}

- Timestamp: ${ctx.reportTimestamp}
- Scan intensity: ${ctx.scanIntensity}

---

# ${ctx.target} Reconnaissance Report

`;
const parkedNote = '## 6-7. Attack Narrative (parked)

_Free-form attack-chain synthesis (Sections 6-7) is temporarily disabled pending the deterministic finding-chaining rework - tool selection was being guessed by the local model rather than derived from the finding itself. Re-enable once findings are routed through rule-based tool selection instead of free-form LLM judgment._

';
const reportContent = header + ctx.sections1to5 + '
' + parkedNote + ctx.section8 + '
';
return [{ json: { ...ctx, reportContent } }];

const ctx = $json;
const jsUrls = (ctx.webScan && ctx.webScan.fingerprint && ctx.webScan.fingerprint.jsAssetUrls) || [];
if (jsUrls.length === 0) {
  return [{ json: { ...ctx, command: 'echo \'{"data":[]}\'' } }];
}
const dlCmds = jsUrls.map((u, i) => `curl -s -m 15 -o /tmp/retire-assets/asset${i}.js "${u}"`).join(' && ');
const command = `mkdir -p /tmp/retire-assets && rm -f /tmp/retire-assets/* && ${dlCmds} && retire --path /tmp/retire-assets --outputformat json --exitwith 0 2>/dev/null || echo '{"data":[]}'`;
return [{ json: { ...ctx, command } }];

const ctx = $('Build Component Scan Command').item.json;
let componentFindings = [];
try {
  const out = JSON.parse($json.stdout || '{"data":[]}');
  for (const file of (out.data || [])) {
    for (const res of (file.results || [])) {
      for (const vuln of (res.vulnerabilities || [])) {
        componentFindings.push({
          component: res.component,
          version: res.version,
          severity: vuln.severity || 'unknown',
          summary: (vuln.identifiers && vuln.identifiers.summary) || null,
          cve: (vuln.identifiers && vuln.identifiers.CVE) || [],
          info: vuln.info || [],
        });
      }
    }
  }
} catch (e) { componentFindings = []; }
return [{ json: { ...ctx, componentFindings } }];

const ctx = $json;
const lines = [];
const p = (s='') => lines.push(s);

// --- 1. MITRE ATT&CK Reconnaissance (TA0043) Coverage ---
p('## 1. MITRE ATT&CK Reconnaissance (TA0043) Coverage');
p('');
p('| Technique | Name | Status |');
p('|---|---|---|');
for (const c of (ctx.attckCoverage || [])) p(`| ${c.technique} | ${c.name} | ${c.status} |`);
p('');
p('Out of scope: T1589/T1591/T1593.001/T1598 (people/social engineering, explicitly excluded). T1597 (Search Closed Sources) requires paid threat-intel access not available in this platform.');
p('');

// --- 2. Attack Surface Summary ---
p('## 2. Attack Surface Summary');
p('');
p(`- Target: \`${ctx.target}\` (resolved IP: \`${ctx.resolvedIp || 'none'}\`)`);
p(`- Subdomains discovered: ${(ctx.subdomains || []).length}`);
const openPortsList = (ctx.portScan && !ctx.portScan.skipped) ? ctx.portScan.openPorts.map(o => `${o.port}/${o.protocol} (${o.service})`).join(', ') : 'port scan not run';
p(`- Open ports: ${openPortsList || 'none found'}`);
p(`- Web application reachable: ${ctx.webScan ? (ctx.webScan.reachable ? 'yes, at ' + ctx.webScan.origin : 'no') : 'not attempted'}`);
p('');
if (ctx.escalationRecommendation) { p(`**Executive Risk Summary:** ${ctx.escalationRecommendation}`); }
p('');

// --- 3. DNS, WHOIS & Subdomains ---
p('## 3. DNS, WHOIS & Subdomains');
p('');
const dns = ctx.dns || {};
for (const rt of ['A','AAAA','MX','NS','TXT','SOA']) {
  const vals = dns[rt] || [];
  p(`- **${rt}**: ${vals.length ? vals.join(', ') : 'none'}`);
}
const whoisKeys = Object.keys(ctx.whois || {});
p(`- **WHOIS**: ${whoisKeys.length ? whoisKeys.map(k => `${k}: ${ctx.whois[k]}`).join('; ') : 'no data returned'}`);
p(`- **Subdomains**: ${(ctx.subdomains || []).length ? ctx.subdomains.join(', ') : 'none discovered'}`);
p('');

// --- 4. Open Ports & Services ---
p('## 4. Open Ports & Services');
p('');
if (!ctx.portScan || ctx.portScan.skipped) {
  p(`Port scan not run (${ctx.portScan ? ctx.portScan.reason : 'scan intensity too low'}).`);
} else if (!ctx.portScan.openPorts.length) {
  p('Port scan ran, no open ports found in the scanned range.');
} else {
  p('| Port | Protocol | Service (nmap-identified) | Product/Version |');
  p('|---|---|---|---|');
  for (const o of ctx.portScan.openPorts) p(`| ${o.port} | ${o.protocol} | ${o.service} | ${o.product ? (o.product + (o.version ? ' ' + o.version : '')) : 'not detected'} |`);
  p('');
  p('#### Per-Port Script Findings');
  const knownSecurityChecks = {
    'ftp-anon': { label: 'Anonymous FTP login', positive: 'Anonymous login allowed', negative: 'Anonymous login not allowed' },
    'smb-os-discovery': { label: 'SMB OS discovery', positive: null, negative: 'No SMB service / discovery produced no data' },
  };
  let anyScriptOutput = false;
  for (const o of ctx.portScan.openPorts) {
    const nonVulnersScripts = (o.scripts || []).filter(s => s.id !== 'vulners');
    const ranIds = new Set(nonVulnersScripts.map(s => s.id));
    for (const [scriptId, meta] of Object.entries(knownSecurityChecks)) {
      if (o.service !== 'ftp' && scriptId === 'ftp-anon') continue;
      const hit = nonVulnersScripts.find(s => s.id === scriptId);
      anyScriptOutput = true;
      if (hit) {
        p(`- Port ${o.port} (\`${scriptId}\`): **${meta.positive || hit.output}** - \`${hit.output}\``);
      } else if (o.service === 'ftp' || scriptId !== 'ftp-anon') {
        p(`- Port ${o.port} (\`${scriptId}\`): tested, no positive result - ${meta.negative}.`);
      }
    }
    for (const s of nonVulnersScripts) {
      if (knownSecurityChecks[s.id]) continue;
      anyScriptOutput = true;
      p(`- Port ${o.port} (\`${s.id}\`): ${s.output}`);
    }
  }
  if (!anyScriptOutput) p('- No NSE script findings for any open port.');
}
p('');

// --- 5. Confirmed Findings (Evidence-Backed) ---
p('## 5. Confirmed Findings (Evidence-Backed)');
p('');
if (ctx.webScan && ctx.webScan.reachable) {
  const ws = ctx.webScan;
  p('### Missing Security Headers');
  if (ws.securityHeaders.missing.length) {
    for (const h of ws.securityHeaders.missing) p(`- \`${h}\`: not set`);
  } else { p('- None missing - all checked headers present.'); }
  p('');
  p('### Cookies');
  if (ws.cookies.length) {
    for (const c of ws.cookies) p(`- \`${c.name}\`: Secure=${c.secure}, HttpOnly=${c.httpOnly}, SameSite=${c.sameSite}`);
  } else { p('- No cookies observed.'); }
  p('');
  p('### Content Discovery (baselined - soft-404s already excluded)');
  const hits = (ws.contentDiscovery || []).filter(r => r.distinctFromBaseline);
  if (hits.length) {
    p('| Path | Status | Source |');
    p('|---|---|---|');
    for (const h of hits) p(`| \`${h.path}\` | ${h.status} | ${h.fromAjaxSpider ? 'observed via AJAX spider' : (h.fromJsBundle ? 'discovered in JS bundle (not linked anywhere)' : 'wordlist')} |`);
