// Real-time/protocol paths (Socket.IO, webpack HMR, etc.) generate many
// near-duplicate requests differing only by a volatile handshake token
// (t=/sid=) - collapse those into one representative entry per path instead
// of flooding the report with dozens of "distinct" findings that are really
// the same one fact ("this app uses Socket.IO").
const infraPathRe = /\/(socket\.io|sockjs-node|__webpack_hmr|hot-update)\//i;
const infraParamRe = /^(EIO|transport|sid|t|callback|jsonp)$/i;
function normalizeForDedup(url) {
  const [base, qs] = url.split('?');
  if (!infraPathRe.test(base) || !qs) return url;
  const kept = qs.split('&').filter(p => !infraParamRe.test(p.split('=')[0]));
  return kept.length ? base + '?' + kept.join('&') : base;
}

const seen = new Set();
const discovered = [];
for (const r of raw) {
  const line = (r.requestHeader || '').split('\r\n')[0] || '';
  const m = line.match(/^(GET|POST|PUT|DELETE)\s+(\S+)/);
  if (!m) continue;
  const method = m[1];
  const url = m[2];
  if (!url.startsWith(ws.origin)) continue;
  const dedupKey = method + ' ' + normalizeForDedup(url);
  if (seen.has(dedupKey)) continue;
  seen.add(dedupKey);
  discovered.push({ method, url, body: r.requestBody || '' });
}

const existingPaths = new Set((ws.contentDiscovery || []).map(p => p.path));
const newContentEntries = [];
for (const d of discovered) {
  const path = d.url.slice(ws.origin.length) || '/';
  const bareePath = path.split('?')[0];
  if (existingPaths.has(bareePath) || existingPaths.has(path)) continue;
  existingPaths.add(path);
  newContentEntries.push({ path, status: 'observed', distinctFromBaseline: true, fromAjaxSpider: true });
}

