      };
      g.count++;
      if (c.isExploit) g.hasExploit = true;
      if (c.cvss > g.maxCvss) { g.maxCvss = c.cvss; g.topId = c.id; }
      groups.set(key, g);
    }
  }
}
const cveSummary = [...groups.values()].sort((a, b) => b.maxCvss - a.maxCvss).slice(0, 8);
return [{ json: { ...ctx, cveSummary } }];
